  1→package jlsm.table.internal;
  2→
  3→import java.lang.foreign.Arena;
  4→import java.lang.foreign.MemorySegment;
  5→import java.lang.foreign.ValueLayout;
  6→import java.nio.ByteOrder;
  7→import java.nio.charset.StandardCharsets;
  8→import java.util.Objects;
  9→
 10→import jlsm.table.FieldType;
 11→
 12→/**
 13→ * Encodes field values into sort-preserving binary form for secondary index keys.
 14→ *
 15→ * <p>
 16→ * Encoding rules (sort-preserving):
 17→ * <ul>
 18→ * <li>INT8/INT16/INT32/INT64: sign-bit-flipped big-endian</li>
 19→ * <li>FLOAT32/FLOAT64: IEEE 754 sort-preserving encoding</li>
 20→ * <li>FLOAT16: sign-bit-flipped big-endian on the 2-byte representation</li>
 21→ * <li>STRING: UTF-8 bytes</li>
 22→ * <li>BOOLEAN: 0x00 for false, 0x01 for true</li>
 23→ * <li>TIMESTAMP: same as INT64 (epoch millis)</li>
 24→ * </ul>
 25→ */
 26→public final class FieldValueCodec {
 27→
 28→    private static final ValueLayout.OfByte BE_BYTE = ValueLayout.JAVA_BYTE
 29→            .withOrder(ByteOrder.BIG_ENDIAN);
 30→    private static final ValueLayout.OfShort BE_SHORT = ValueLayout.JAVA_SHORT_UNALIGNED
 31→            .withOrder(ByteOrder.BIG_ENDIAN);
 32→    private static final ValueLayout.OfInt BE_INT = ValueLayout.JAVA_INT_UNALIGNED
 33→            .withOrder(ByteOrder.BIG_ENDIAN);
 34→    private static final ValueLayout.OfLong BE_LONG = ValueLayout.JAVA_LONG_UNALIGNED
 35→            .withOrder(ByteOrder.BIG_ENDIAN);
 36→
 37→    private FieldValueCodec() {
 38→    }
 39→
 40→    public static MemorySegment encode(Object value, FieldType fieldType) {
 41→        Objects.requireNonNull(fieldType, "fieldType");
 42→        if (!(fieldType instanceof FieldType.Primitive p)) {
 43→            throw new IllegalArgumentException(
 44→                    "Only primitive field types can be encoded, got: " + fieldType);
 45→        }
 46→        Objects.requireNonNull(value, "value");
 47→        return switch (p) {
 48→            case INT8 -> encodeInt8(value);
 49→            case INT16 -> encodeInt16(value);
 50→            case INT32 -> encodeInt32(value);
 51→            case INT64 -> encodeInt64(value);
 52→            case FLOAT16 -> encodeFloat16(value);
 53→            case FLOAT32 -> encodeFloat32(value);
 54→            case FLOAT64 -> encodeFloat64(value);
 55→            case STRING -> encodeString(value);
 56→            case BOOLEAN -> encodeBoolean(value);
 57→            case TIMESTAMP -> encodeTimestamp(value);
 58→        };
 59→    }
 60→
 61→    public static Object decode(MemorySegment encoded, FieldType fieldType) {
 62→        Objects.requireNonNull(encoded, "encoded");
 63→        Objects.requireNonNull(fieldType, "fieldType");
 64→        if (!(fieldType instanceof FieldType.Primitive p)) {
 65→            throw new IllegalArgumentException(
 66→                    "Only primitive field types can be decoded, got: " + fieldType);
 67→        }
 68→        return switch (p) {
 69→            case INT8 -> decodeInt8(encoded);
 70→            case INT16 -> decodeInt16(encoded);
 71→            case INT32 -> decodeInt32(encoded);
 72→            case INT64 -> decodeInt64(encoded);
 73→            case FLOAT16 -> decodeFloat16(encoded);
 74→            case FLOAT32 -> decodeFloat32(encoded);
 75→            case FLOAT64 -> decodeFloat64(encoded);
 76→            case STRING -> decodeString(encoded);
 77→            case BOOLEAN -> decodeBoolean(encoded);
 78→            case TIMESTAMP -> decodeTimestamp(encoded);
 79→        };
 80→    }
 81→
 82→    // ── INT8 ────────────────────────────────────────────────────────────
 83→
 84→    private static MemorySegment encodeInt8(Object value) {
 85→        if (!(value instanceof Byte b)) {
 86→            throw new IllegalArgumentException(
 87→                    "INT8 requires Byte, got: " + value.getClass().getSimpleName());
 88→        }
 89→        MemorySegment seg = Arena.ofAuto().allocate(1);
 90→        seg.set(BE_BYTE, 0, (byte) (b ^ Byte.MIN_VALUE));
 91→        return seg;
 92→    }
 93→
 94→    private static byte decodeInt8(MemorySegment encoded) {
 95→        assert encoded.byteSize() == 1 : "INT8 expects 1 byte";
 96→        return (byte) (encoded.get(BE_BYTE, 0) ^ Byte.MIN_VALUE);
 97→    }
 98→
 99→    // ── INT16 ───────────────────────────────────────────────────────────
100→
101→    private static MemorySegment encodeInt16(Object value) {
102→        if (!(value instanceof Short s)) {
103→            throw new IllegalArgumentException(
104→                    "INT16 requires Short, got: " + value.getClass().getSimpleName());
105→        }
106→        MemorySegment seg = Arena.ofAuto().allocate(2);
107→        seg.set(BE_SHORT, 0, (short) (s ^ Short.MIN_VALUE));
108→        return seg;
109→    }
110→
111→    private static short decodeInt16(MemorySegment encoded) {
112→        assert encoded.byteSize() == 2 : "INT16 expects 2 bytes";
113→        return (short) (encoded.get(BE_SHORT, 0) ^ Short.MIN_VALUE);
114→    }
115→
116→    // ── INT32 ───────────────────────────────────────────────────────────
117→
118→    private static MemorySegment encodeInt32(Object value) {
119→        if (!(value instanceof Integer i)) {
120→            throw new IllegalArgumentException(
121→                    "INT32 requires Integer, got: " + value.getClass().getSimpleName());
122→        }
123→        MemorySegment seg = Arena.ofAuto().allocate(4);
124→        seg.set(BE_INT, 0, i ^ Integer.MIN_VALUE);
125→        return seg;
126→    }
127→
128→    private static int decodeInt32(MemorySegment encoded) {
129→        assert encoded.byteSize() == 4 : "INT32 expects 4 bytes";
130→        return encoded.get(BE_INT, 0) ^ Integer.MIN_VALUE;
131→    }
132→
133→    // ── INT64 ───────────────────────────────────────────────────────────
134→
135→    private static MemorySegment encodeInt64(Object value) {
136→        if (!(value instanceof Long l)) {
137→            throw new IllegalArgumentException(
138→                    "INT64 requires Long, got: " + value.getClass().getSimpleName());
139→        }
140→        return encodeInt64Raw(l);
141→    }
142→
143→    private static MemorySegment encodeInt64Raw(long l) {
144→        MemorySegment seg = Arena.ofAuto().allocate(8);
145→        seg.set(BE_LONG, 0, l ^ Long.MIN_VALUE);
146→        return seg;
147→    }
148→
149→    private static long decodeInt64(MemorySegment encoded) {
150→        assert encoded.byteSize() == 8 : "INT64 expects 8 bytes";
151→        return encoded.get(BE_LONG, 0) ^ Long.MIN_VALUE;
152→    }
153→
154→    // ── FLOAT16 ─────────────────────────────────────────────────────────
155→
156→    private static MemorySegment encodeFloat16(Object value) {
157→        if (!(value instanceof Short s)) {
158→            throw new IllegalArgumentException(
159→                    "FLOAT16 requires Short (raw bits), got: " + value.getClass().getSimpleName());
160→        }
161→        MemorySegment seg = Arena.ofAuto().allocate(2);
162→        int bits = s & 0xFFFF;
163→        if ((bits & 0x8000) != 0) {
164→            bits = ~bits & 0xFFFF;
165→        } else {
166→            bits = bits | 0x8000;
167→        }
168→        seg.set(BE_SHORT, 0, (short) bits);
169→        return seg;
170→    }
171→
172→    private static short decodeFloat16(MemorySegment encoded) {
173→        assert encoded.byteSize() == 2 : "FLOAT16 expects 2 bytes";
174→        int bits = encoded.get(BE_SHORT, 0) & 0xFFFF;
175→        if ((bits & 0x8000) != 0) {
176→            bits = bits & 0x7FFF;
177→        } else {
178→            bits = ~bits & 0xFFFF;
179→        }
180→        return (short) bits;
181→    }
182→
183→    // ── FLOAT32 ─────────────────────────────────────────────────────────
184→
185→    private static MemorySegment encodeFloat32(Object value) {
186→        if (!(value instanceof Float f)) {
187→            throw new IllegalArgumentException(
188→                    "FLOAT32 requires Float, got: " + value.getClass().getSimpleName());
189→        }
190→        int bits = Float.floatToRawIntBits(f);
191→        if (bits < 0) {
192→            bits = ~bits;
193→        } else {
194→            bits = bits | Integer.MIN_VALUE;
195→        }
196→        MemorySegment seg = Arena.ofAuto().allocate(4);
197→        seg.set(BE_INT, 0, bits);
198→        return seg;
199→    }
200→
201→    private static float decodeFloat32(MemorySegment encoded) {
202→        assert encoded.byteSize() == 4 : "FLOAT32 expects 4 bytes";
203→        int bits = encoded.get(BE_INT, 0);
204→        if (bits < 0) {
205→            bits = bits & Integer.MAX_VALUE;
206→        } else {
207→            bits = ~bits;
208→        }
209→        return Float.intBitsToFloat(bits);
210→    }
211→
212→    // ── FLOAT64 ─────────────────────────────────────────────────────────
213→
214→    private static MemorySegment encodeFloat64(Object value) {
215→        if (!(value instanceof Double d)) {
216→            throw new IllegalArgumentException(
217→                    "FLOAT64 requires Double, got: " + value.getClass().getSimpleName());
218→        }
219→        long bits = Double.doubleToRawLongBits(d);
220→        if (bits < 0) {
221→            bits = ~bits;
222→        } else {
223→            bits = bits | Long.MIN_VALUE;
224→        }
225→        MemorySegment seg = Arena.ofAuto().allocate(8);
226→        seg.set(BE_LONG, 0, bits);
227→        return seg;
228→    }
229→
230→    private static double decodeFloat64(MemorySegment encoded) {
231→        assert encoded.byteSize() == 8 : "FLOAT64 expects 8 bytes";
232→        long bits = encoded.get(BE_LONG, 0);
233→        if (bits < 0) {
234→            bits = bits & Long.MAX_VALUE;
235→        } else {
236→            bits = ~bits;
237→        }
238→        return Double.longBitsToDouble(bits);
239→    }
240→
241→    // ── STRING ──────────────────────────────────────────────────────────
242→
243→    private static MemorySegment encodeString(Object value) {
244→        if (!(value instanceof String s)) {
245→            throw new IllegalArgumentException(
246→                    "STRING requires String, got: " + value.getClass().getSimpleName());
247→        }
248→        byte[] utf8 = s.getBytes(StandardCharsets.UTF_8);
249→        MemorySegment seg = Arena.ofAuto().allocate(utf8.length);
250→        MemorySegment.copy(utf8, 0, seg, ValueLayout.JAVA_BYTE, 0, utf8.length);
251→        return seg;
252→    }
253→
254→    private static String decodeString(MemorySegment encoded) {
255→        byte[] bytes = encoded.toArray(ValueLayout.JAVA_BYTE);
256→        return new String(bytes, StandardCharsets.UTF_8);
257→    }
258→
259→    // ── BOOLEAN ─────────────────────────────────────────────────────────
260→
261→    private static MemorySegment encodeBoolean(Object value) {
262→        if (!(value instanceof Boolean b)) {
263→            throw new IllegalArgumentException(
264→                    "BOOLEAN requires Boolean, got: " + value.getClass().getSimpleName());
265→        }
266→        MemorySegment seg = Arena.ofAuto().allocate(1);
267→        seg.set(BE_BYTE, 0, b ? (byte) 0x01 : (byte) 0x00);
268→        return seg;
269→    }
270→
271→    private static boolean decodeBoolean(MemorySegment encoded) {
272→        assert encoded.byteSize() == 1 : "BOOLEAN expects 1 byte";
273→        return encoded.get(BE_BYTE, 0) != 0;
274→    }
275→
276→    // ── TIMESTAMP ───────────────────────────────────────────────────────
277→
278→    private static MemorySegment encodeTimestamp(Object value) {
279→        if (!(value instanceof Long l)) {
280→            throw new IllegalArgumentException(
281→                    "TIMESTAMP requires Long, got: " + value.getClass().getSimpleName());
282→        }
283→        return encodeInt64Raw(l);
284→    }
285→
286→    private static long decodeTimestamp(MemorySegment encoded) {
287→        return decodeInt64(encoded);
288→    }
289→}
290→

  1→package jlsm.table;
  2→
  3→import jlsm.core.io.MemorySerializer;
  4→import jdk.incubator.vector.ByteVector;
  5→import jdk.incubator.vector.DoubleVector;
  6→import jdk.incubator.vector.FloatVector;
  7→import jdk.incubator.vector.IntVector;
  8→import jdk.incubator.vector.LongVector;
  9→import jdk.incubator.vector.VectorShuffle;
 10→import jdk.incubator.vector.VectorSpecies;
 11→
 12→import java.lang.foreign.MemorySegment;
 13→import java.lang.foreign.ValueLayout;
 14→import java.nio.charset.StandardCharsets;
 15→import java.util.List;
 16→import java.util.Objects;
 17→
 18→/**
 19→ * Binary serializer for {@link JlsmDocument} values.
 20→ *
 21→ * <p>
 22→ * The binary format consists of a header (schema version, field count, null bitmask, optional
 23→ * boolean bitmask) followed by serialized non-null, non-boolean field values in schema order.
 24→ *
 25→ * <p>
 26→ * Schema versioning: the header stores the write-time field count. On deserialization with a newer
 27→ * schema, only the write-time fields are decoded; additional fields in the current schema are left
 28→ * {@code null}.
 29→ *
 30→ * <p>
 31→ * Contiguous numeric arrays (INT32, INT64, FLOAT32, FLOAT64) use SIMD byte-swap acceleration via
 32→ * {@code jdk.incubator.vector}.
 33→ */
 34→public final class DocumentSerializer {
 35→
 36→    private DocumentSerializer() {
 37→    }
 38→
 39→    /**
 40→     * Returns a {@link MemorySerializer} for {@link JlsmDocument} values conforming to the given
 41→     * schema.
 42→     *
 43→     * @param schema the schema describing the document structure; must not be null
 44→     * @return a MemorySerializer for JlsmDocument
 45→     */
 46→    public static MemorySerializer<JlsmDocument> forSchema(JlsmSchema schema) {
 47→        Objects.requireNonNull(schema, "schema must not be null");
 48→        return new SchemaSerializer(schema);
 49→    }
 50→
 51→    // =========================================================================
 52→    // Implementation
 53→    // =========================================================================
 54→
 55→    /** SIMD species for byte-level operations (used for byte-swap shuffles). */
 56→    private static final VectorSpecies<Byte> BYTE_SPECIES = ByteVector.SPECIES_PREFERRED;
 57→
 58→    /** Byte-swap shuffle for INT32 / FLOAT32 (4-byte elements). */
 59→    private static final VectorShuffle<Byte> BSWAP32;
 60→
 61→    /** Byte-swap shuffle for INT64 / FLOAT64 (8-byte elements). */
 62→    private static final VectorShuffle<Byte> BSWAP64;
 63→
 64→    static {
 65→        final int byteLen = BYTE_SPECIES.length();
 66→        final int[] idx32 = new int[byteLen];
 67→        final int[] idx64 = new int[byteLen];
 68→        for (int i = 0; i + 3 < byteLen; i += 4) {
 69→            idx32[i + 0] = i + 3;
 70→            idx32[i + 1] = i + 2;
 71→            idx32[i + 2] = i + 1;
 72→            idx32[i + 3] = i + 0;
 73→        }
 74→        for (int i = 0; i + 7 < byteLen; i += 8) {
 75→            idx64[i + 0] = i + 7;
 76→            idx64[i + 1] = i + 6;
 77→            idx64[i + 2] = i + 5;
 78→            idx64[i + 3] = i + 4;
 79→            idx64[i + 4] = i + 3;
 80→            idx64[i + 5] = i + 2;
 81→            idx64[i + 6] = i + 1;
 82→            idx64[i + 7] = i + 0;
 83→        }
 84→        BSWAP32 = VectorShuffle.fromArray(BYTE_SPECIES, idx32, 0);
 85→        BSWAP64 = VectorShuffle.fromArray(BYTE_SPECIES, idx64, 0);
 86→    }
 87→
 88→    // -------------------------------------------------------------------------
 89→    // Serializer implementation
 90→    // -------------------------------------------------------------------------
 91→
 92→    private static final class SchemaSerializer implements MemorySerializer<JlsmDocument> {
 93→
 94→        private final JlsmSchema schema;
 95→
 96→        SchemaSerializer(JlsmSchema schema) {
 97→            this.schema = schema;
 98→        }
 99→
100→        @Override
101→        public MemorySegment serialize(JlsmDocument doc) {
102→            Objects.requireNonNull(doc, "doc must not be null");
103→            assert doc.schema() == schema || doc.schema().name().equals(schema.name())
104→                    : "document schema mismatch";
105→
106→            final List<FieldDefinition> fields = schema.fields();
107→            final int fieldCount = fields.size();
108→            final Object[] values = doc.values();
109→
110→            // Count boolean fields
111→            final int boolCount = countBoolFields(fields);
112→
113→            // Header size: 2 (version) + 2 (fieldCount) + ceil(fieldCount/8) (null mask)
114→            // + (boolCount > 0 ? ceil(boolCount/8) : 0) (bool mask)
115→            final int nullMaskBytes = (fieldCount + 7) / 8;
116→            final int boolMaskBytes = boolCount > 0 ? (boolCount + 7) / 8 : 0;
117→            final int headerSize = 2 + 2 + nullMaskBytes + boolMaskBytes;
118→
119→            // Two-pass: measure then encode
120→            final int payloadSize = measureFields(fields, values);
121→            final int totalSize = headerSize + payloadSize;
122→
123→            final byte[] buf = new byte[totalSize];
124→
125→            // Write header
126→            writeShortBE(buf, 0, (short) schema.version());
127→            writeShortBE(buf, 2, (short) fieldCount);
128→            // Null bitmask
129→            buildNullMask(fields, values, buf, 4);
130→            // Boolean bitmask
131→            if (boolCount > 0) {
132→                buildBoolMask(fields, values, buf, 4 + nullMaskBytes);
133→            }
134→
135→            // Write values
136→            final Cursor cursor = new Cursor(buf, headerSize);
137→            encodeFields(fields, values, cursor);
138→
139→            assert cursor.pos == totalSize : "cursor.pos should equal totalSize";
140→            return MemorySegment.ofArray(buf);
141→        }
142→
143→        @Override
144→        public JlsmDocument deserialize(MemorySegment segment) {
145→            Objects.requireNonNull(segment, "segment must not be null");
146→
147→            final byte[] buf = segment.toArray(ValueLayout.JAVA_BYTE);
148→            final Cursor cursor = new Cursor(buf, 0);
149→
150→            // Read header
151→            final int _ = readShortBE(buf, cursor.advance(2)) & 0xFFFF;
152→            final int writeFieldCount = readShortBE(buf, cursor.advance(2)) & 0xFFFF;
153→
154→            final List<FieldDefinition> currentFields = schema.fields();
155→            final int currentFieldCount = currentFields.size();
156→
157→            // We only read min(writeFieldCount, currentFieldCount) fields
158→            final int readCount = Math.min(writeFieldCount, currentFieldCount);
159→
160→            // Count bool fields in the *write-time* schema (same field list up to writeFieldCount)
161→            // We use the current schema's first writeFieldCount fields for the null/bool masks.
162→            // For the boolMask we count booleans among the first writeFieldCount fields.
163→            final int writeBoolCount = countBoolFieldsUpTo(currentFields, writeFieldCount);
164→            final int writeNullMaskBytes = (writeFieldCount + 7) / 8;
165→            final int writeBoolMaskBytes = writeBoolCount > 0 ? (writeBoolCount + 7) / 8 : 0;
166→
167→            final int nullMaskOffset = cursor.advance(writeNullMaskBytes);
168→            final int boolMaskOffset = writeBoolCount > 0 ? cursor.advance(writeBoolMaskBytes) : -1;
169→
170→            // Decode values
171→            final Object[] values = new Object[currentFieldCount];
172→            // Fields beyond readCount remain null (new fields added in a later schema version)
173→
174→            int boolIdx = 0; // index among BOOLEAN fields seen so far
175→            for (int i = 0; i < readCount; i++) {
176→                final FieldDefinition fd = currentFields.get(i);
177→                final boolean isNull = isNullBit(buf, nullMaskOffset, i);
178→                if (isNull) {
179→                    // Track bool index even when null
180→                    if (fd.type() == FieldType.Primitive.BOOLEAN) {
181→                        boolIdx++;
182→                    }
183→                    values[i] = null;
184→                    continue;
185→                }
186→                if (fd.type() == FieldType.Primitive.BOOLEAN) {
187→                    // Value is encoded in the bool bitmask
188→                    assert boolMaskOffset >= 0 : "bool bitmask offset should be set";
189→                    values[i] = isBoolBit(buf, boolMaskOffset, boolIdx);
190→                    boolIdx++;
191→                } else {
192→                    values[i] = decodeField(buf, cursor, fd.type());
193→                }
194→            }
195→
196→            // If writeFieldCount > currentFieldCount we need to skip the extra encoded fields.
197→            // However, since we can't know the sizes of unknown fields (their types may differ
198→            // from the current schema), we handle schema shrinkage gracefully by only reading
199→            // min(writeFieldCount, currentFieldCount). Extra write-time fields beyond the current
200→            // schema are simply ignored — the cursor position won't matter after this point.
201→
202→            return new JlsmDocument(schema, values);
203→        }
204→    }
205→
206→    // =========================================================================
207→    // Measure helpers (first pass)
208→    // =========================================================================
209→
210→    private static int measureFields(List<FieldDefinition> fields, Object[] values) {
211→        int total = 0;
212→        for (int i = 0; i < fields.size(); i++) {
213→            final FieldDefinition fd = fields.get(i);
214→            final Object val = values[i];
215→            if (val == null) {
216→                continue; // null → no value bytes
217→            }
218→            total += measureField(fd.type(), val);
219→        }
220→        return total;
221→    }
222→
223→    private static int measureField(FieldType type, Object value) {
224→        return switch (type) {
225→            case FieldType.Primitive p -> switch (p) {
226→                case STRING -> {
227→                    final byte[] utf8 = ((String) value).getBytes(StandardCharsets.UTF_8);
228→                    yield varIntSize(utf8.length) + utf8.length;
229→                }
230→                case INT8 -> 1;
231→                case INT16 -> 2;
232→                case INT32 -> 4;
233→                case INT64 -> 8;
234→                case FLOAT16 -> 2;
235→                case FLOAT32 -> 4;
236→                case FLOAT64 -> 8;
237→                case BOOLEAN -> 0; // packed in bitmask
238→                case TIMESTAMP -> 8;
239→            };
240→            case FieldType.ArrayType at -> {
241→                final Object[] arr = (Object[]) value;
242→                int sz = varIntSize(arr.length);
243→                for (Object elem : arr) {
244→                    sz += (elem == null) ? 0 : measureField(at.elementType(), elem);
245→                }
246→                yield sz;
247→            }
248→            case FieldType.ObjectType ot -> {
249→                final JlsmDocument sub = (JlsmDocument) value;
250→                final List<FieldDefinition> subFields = ot.fields();
251→                final int subBoolCount = countBoolFields(subFields);
252→                final int subNullBytes = (subFields.size() + 7) / 8;
253→                final int subBoolBytes = subBoolCount > 0 ? (subBoolCount + 7) / 8 : 0;
254→                int sz = subNullBytes + subBoolBytes;
255→                sz += measureFields(subFields, sub.values());
256→                yield sz;
257→            }
258→        };
259→    }
260→
261→    // =========================================================================
262→    // Encode helpers (second pass)
263→    // =========================================================================
264→
265→    private static void encodeFields(List<FieldDefinition> fields, Object[] values, Cursor c) {
266→        for (int i = 0; i < fields.size(); i++) {
267→            final Object val = values[i];
268→            if (val == null) {
269→                continue;
270→            }
271→            encodeField(c, fields.get(i).type(), val);
272→        }
273→    }
274→
275→    private static void encodeField(Cursor c, FieldType type, Object value) {
276→        switch (type) {
277→            case FieldType.Primitive p -> {
278→                switch (p) {
279→                    case STRING -> {
280→                        final byte[] utf8 = ((String) value).getBytes(StandardCharsets.UTF_8);
281→                        writeVarInt(c, utf8.length);
282→                        System.arraycopy(utf8, 0, c.buf, c.pos, utf8.length);
283→                        c.pos += utf8.length;
284→                    }
285→                    case INT8 -> c.buf[c.pos++] = (Byte) value;
286→                    case INT16 -> {
287→                        writeShortBE(c.buf, c.pos, (Short) value);
288→                        c.pos += 2;
289→                    }
290→                    case INT32 -> {
291→                        writeIntBE(c.buf, c.pos, (Integer) value);
292→                        c.pos += 4;
293→                    }
294→                    case INT64 -> {
295→                        writeLongBE(c.buf, c.pos, (Long) value);
296→                        c.pos += 8;
297→                    }
298→                    case FLOAT16 -> {
299→                        writeShortBE(c.buf, c.pos, (Short) value);
300→                        c.pos += 2;
301→                    }
302→                    case FLOAT32 -> {
303→                        writeIntBE(c.buf, c.pos, Float.floatToRawIntBits((Float) value));
304→                        c.pos += 4;
305→                    }
306→                    case FLOAT64 -> {
307→                        writeLongBE(c.buf, c.pos, Double.doubleToRawLongBits((Double) value));
308→                        c.pos += 8;
309→                    }
310→                    case BOOLEAN -> {
311→                        // Boolean values are packed in the bool bitmask; nothing here
312→                    }
313→                    case TIMESTAMP -> {
314→                        writeLongBE(c.buf, c.pos, (Long) value);
315→                        c.pos += 8;
316→                    }
317→                }
318→            }
319→            case FieldType.ArrayType at -> encodeArray(c, at.elementType(), (Object[]) value);
320→            case FieldType.ObjectType ot -> encodeObject(c, ot, (JlsmDocument) value);
321→        }
322→    }
323→
324→    private static void encodeArray(Cursor c, FieldType elemType, Object[] arr) {
325→        writeVarInt(c, arr.length);
326→        // SIMD-accelerated paths for contiguous numeric types
327→        if (elemType == FieldType.Primitive.INT32) {
328→            encodeInt32Array(c, arr);
329→        } else if (elemType == FieldType.Primitive.INT64) {
330→            encodeInt64Array(c, arr);
331→        } else if (elemType == FieldType.Primitive.FLOAT32) {
332→            encodeFloat32Array(c, arr);
333→        } else if (elemType == FieldType.Primitive.FLOAT64) {
334→            encodeFloat64Array(c, arr);
335→        } else {
336→            for (Object elem : arr) {
337→                if (elem != null) {
338→                    encodeField(c, elemType, elem);
339→                }
340→            }
341→        }
342→    }
343→
344→    private static void encodeObject(Cursor c, FieldType.ObjectType ot, JlsmDocument sub) {
345→        final List<FieldDefinition> subFields = ot.fields();
346→        final Object[] subValues = sub.values();
347→        final int boolCount = countBoolFields(subFields);
348→        final int nullMaskBytes = (subFields.size() + 7) / 8;
349→        final int boolMaskBytes = boolCount > 0 ? (boolCount + 7) / 8 : 0;
350→
351→        final int nullMaskStart = c.pos;
352→        c.pos += nullMaskBytes;
353→        final int boolMaskStart = boolCount > 0 ? c.pos : -1;
354→        if (boolCount > 0) {
355→            c.pos += boolMaskBytes;
356→        }
357→
358→        buildNullMask(subFields, subValues, c.buf, nullMaskStart);
359→        if (boolCount > 0) {
360→            buildBoolMask(subFields, subValues, c.buf, boolMaskStart);
361→        }
362→        encodeFields(subFields, subValues, c);
363→    }
