733→    // =========================================================================
734→    // VarInt (LEB128 unsigned)
735→    // =========================================================================
736→
737→    private static int varIntSize(int value) {
738→        assert value >= 0 : "VarInt value must be non-negative";
739→        if (value < 128) {
740→            return 1;
741→        }
742→        if (value < 16384) {
743→            return 2;
744→        }
745→        if (value < 2097152) {
746→            return 3;
747→        }
748→        if (value < 268435456) {
749→            return 4;
750→        }
751→        return 5;
752→    }
753→
754→    private static void writeVarInt(Cursor c, int value) {
755→        assert value >= 0 : "VarInt value must be non-negative";
756→        while (true) {
757→            if ((value & ~0x7F) == 0) {
758→                c.buf[c.pos++] = (byte) value;
759→                return;
760→            }
761→            c.buf[c.pos++] = (byte) ((value & 0x7F) | 0x80);
762→            value >>>= 7;
763→        }
764→    }
765→
766→    private static int readVarInt(byte[] buf, Cursor cursor) {
767→        int result = 0;
768→        int shift = 0;
769→        while (true) {
770→            final byte b = buf[cursor.pos++];
771→            result |= (b & 0x7F) << shift;
772→            if ((b & 0x80) == 0) {
773→                break;
774→            }
775→            shift += 7;
776→            assert shift <= 35 : "VarInt overflow — corrupt data";
777→        }
778→        return result;
779→    }
