18→    @Test
19→    void roundTrip_negativeFloat() {
20→        float original = -2.5f;
21→        short bits = Float16.fromFloat(original);
22→        float recovered = Float16.toFloat(bits);
23→        assertEquals(original, recovered, HALF_EPSILON, "negative float roundtrip");
24→    }
